{
  "nl": {
    "issue": [
      {
        "text": "二人以上依法承担连带责任时，权利人如何行使请求权，责任人之间如何确定份额、如何追偿",
        "rules": ["c178-3", "c178-1", "c178-share", "c178-average", "c178-recourse"]
      },
      {
        "text": "承担民事责任有哪些法定方式，能否单独或合并适用，惩罚性赔偿如何处理",
        "rules": ["c179-forms", "c179-3", "c179-2"]
      },
      {
        "text": "同一行为同时引起民事责任、行政责任、刑事责任时，责任如何承担，财产不足时如何清偿",
        "rules": ["c187-1", "c187-2"]
      }
    ],
    "conditions": [
      {
        "text": "连带责任须由法律规定或者当事人约定（法定或约定连带）",
        "rules": ["c178-3"]
      },
      {
        "text": "责任人的责任大小可以确定；难以确定责任大小的，平均承担",
        "rules": ["c178-share", "c178-average"]
      },
      {
        "text": "连带责任人实际承担的责任超过自己的责任份额",
        "rules": ["c178-recourse"]
      },
      {
        "text": "所主张的责任方式属于第179条第1款列举的十一种方式之一",
        "rules": ["c179-forms"]
      },
      {
        "text": "法律对惩罚性赔偿有规定",
        "rules": ["c179-2"]
      },
      {
        "text": "民事主体因同一行为承担行政责任或刑事责任；其财产不足以支付全部责任",
        "rules": ["c187-1", "c187-2"]
      }
    ],
    "exceptions": [
      {
        "text": "责任方式的适用范围受限制：继续履行、支付违约金等仅适用于违约责任；赔礼道歉、消除影响、恢复名誉主要适用于侵权责任，尤其人身权侵害（笔记）",
        "rules": ["c179-doctrine-breach", "c179-doctrine-tort"]
      }
    ],
    "effects": [
      {
        "text": "权利人有权请求部分或者全部连带责任人承担责任",
        "rules": ["c178-1"]
      },
      {
        "text": "连带责任人的责任份额根据各自责任大小确定；难以确定责任大小的，平均承担责任",
        "rules": ["c178-share", "c178-average"]
      },
      {
        "text": "实际承担责任超过自己责任份额的连带责任人，有权向其他连带责任人追偿",
        "rules": ["c178-recourse"]
      },
      {
        "text": "第179条第1款列举的十一种责任方式可以单独适用，也可以合并适用",
        "rules": ["c179-forms", "c179-3"]
      },
      {
        "text": "法律规定惩罚性赔偿的，依照其规定适用",
        "rules": ["c179-2"]
      },
      {
        "text": "承担行政责任或者刑事责任不影响承担民事责任；财产不足以支付的，优先用于承担民事责任",
        "rules": ["c187-1", "c187-2"]
      }
    ],
    "priority": [
      {
        "text": "法律规定惩罚性赔偿的，优先适用该特别规定，而不限于第179条第1款列举的一般责任方式",
        "rules": ["c179-2"]
      },
      {
        "text": "财产不足以支付时，民事责任优先于行政责任、刑事责任受偿",
        "rules": ["c187-2"]
      }
    ],
    "distinguish": [
      {
        "text": "第178条规范连带责任的对外请求、内部份额与追偿，不涉及责任方式本身；第179条规范责任方式的种类与并用",
        "rules": []
      },
      {
        "text": "第177条按份责任侧重责任份额的划分，与连带责任的对外连带、内部追偿不同；第180条不可抗力、第181条正当防卫属免责事由，排除责任成立，与责任方式的选择无关（LEGO 卡片提示）",
        "rules": []
      },
      {
        "text": "笔记标注：赔偿损失也可作为物权保护方式；赔礼道歉为侵权责任方式；消除影响、恢复名誉、赔礼道歉主要适用于人身权侵害",
        "rules": ["c179-doctrine-tort"]
      }
    ]
  },
